import { GRAND_MINT_SERIES, PENTAPORT_SERIES } from '../../data/catalog/ids'
import { isInsideBounds, type LatLng, type LatLngBounds } from '../../lib/geo'
import gmfImage from '../../assets/maps/gmf.webp'
import gmfMeta from '../../assets/maps/gmf.json'
import pentaportMeta from '../../assets/maps/pentaport.json'

/**
 * Illustrated festival maps bundled with the app (generated by scripts/map/).
 * Keyed by festival code (not year): a festival held at the same place every year reuses one map.
 * Kept out of user data, so stored data can never point the app at an image URL.
 */
/** An official-map marker icon (toilet, info, …) moved onto the redrawn map. */
export interface MapMark {
  id: number
  kind: string
  zone: string
  lat: number
  lng: number
  /** Where the map draws the mark, when not at the place itself (a badge set beside its booth). */
  spot?: LatLng
}

/** One image of the map, stretched onto its bounds. A map's layers stay separate images, drawn bottom first. */
export interface MapLayer {
  url: string
  bounds: LatLngBounds
}

export const MAP_LABEL_KINDS = ['station', 'building', 'stage', 'place', 'zone', 'bus'] as const
export type MapLabelKind = (typeof MAP_LABEL_KINDS)[number]

/** A name the app writes on the map at a fixed size (a station, a big building, a stage, a bus stop), from `minZoom` on. */
export interface MapLabel {
  text: string
  kind: MapLabelKind
  lat: number
  lng: number
  minZoom: number
  /** An icon of the map's (a key of `icons`) before the text. */
  icon?: string
  /** A small coloured tag before the text (a subway line: "인천1"). */
  badge?: { text: string; colour: string }
  colour?: string
}

export interface FestivalMap {
  layers: readonly MapLayer[]
  /** The whole map (every layer inside it). */
  bounds: LatLngBounds
  initialView: LatLngBounds
  /** How far in the images stay sharp; null = the default for raster images. */
  maxZoom: number | null
  /** Open zoomed in until the map fills the screen (a map whose surroundings are blank); false = open on the whole
   *  initial view (a map whose ground runs on in its background colour). */
  fillOnOpen: boolean
  /** Zooming out stops while the map still fills the screen (no empty bands); false = at the whole map. */
  zoomOutFills: boolean
  attribution: string
  /** Shown around the image (it should match the drawing's own background); null = the default paper. */
  background: string | null
  anchors: Record<string, readonly [number, number]>
  marks: readonly MapMark[]
  /** Icons the app draws on the map at a fixed size (key → bundled image URL): catalog pins name one in `mapIcon`. */
  icons: Readonly<Record<string, string>>
  labels: readonly MapLabel[]
}

/** A file of the map's folder, as the metadata names it. */
interface LayerFile {
  file: string
  bounds: LatLngBounds
}
type MapMeta = Omit<FestivalMap, 'layers' | 'icons'> & { layerFiles: readonly LayerFile[]; iconFiles: Readonly<Record<string, string>> }

const isPair = (value: unknown): value is [number, number] =>
  Array.isArray(value) && value.length === 2 && value.every((n) => typeof n === 'number' && Number.isFinite(n))
const isColour = (value: unknown): value is string => typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value)

function toBounds(value: unknown, label: string): LatLngBounds {
  if (!Array.isArray(value) || value.length !== 2 || !isPair(value[0]) || !isPair(value[1])) {
    throw new Error(`map metadata: ${label} must be [[south, west], [north, east]]`)
  }
  const [sw, ne] = value
  if (sw[0] >= ne[0] || sw[1] >= ne[1]) throw new Error(`map metadata: ${label} south-west must be below north-east`)
  return [sw, ne]
}

function toSpot(value: unknown, bounds: LatLngBounds): LatLng | null {
  const s = value as Partial<LatLng>
  const ok = typeof s.lat === 'number' && typeof s.lng === 'number' && isInsideBounds({ lat: s.lat, lng: s.lng }, bounds)
  return ok ? { lat: s.lat!, lng: s.lng! } : null
}

function toLabel(value: unknown, bounds: LatLngBounds, icons: Readonly<Record<string, string>>): MapLabel {
  const l = value as Partial<MapLabel>
  const ok =
    typeof l.text === 'string' &&
    l.text.length > 0 &&
    MAP_LABEL_KINDS.includes(l.kind as MapLabelKind) &&
    typeof l.minZoom === 'number' &&
    typeof l.lat === 'number' &&
    typeof l.lng === 'number' &&
    isInsideBounds({ lat: l.lat, lng: l.lng }, bounds) &&
    (l.icon === undefined || l.icon in icons) &&
    (l.badge === undefined || (typeof l.badge.text === 'string' && l.badge.text.length > 0 && isColour(l.badge.colour)))
  if (!ok) throw new Error(`map metadata: label ${String(l.text)} needs text, a kind, minZoom, a known icon and badge and a lat/lng inside the map`)
  return {
    text: l.text!,
    kind: l.kind!,
    lat: l.lat!,
    lng: l.lng!,
    minZoom: l.minZoom!,
    ...(l.icon ? { icon: l.icon } : {}),
    ...(l.badge ? { badge: { text: l.badge.text, colour: l.badge.colour } } : {}),
    ...(isColour(l.colour) ? { colour: l.colour } : {}),
  }
}

/** Validates the generator's JSON so a bad regeneration fails loudly instead of drawing a broken map. */
export function parseMapMeta(raw: {
  attribution?: unknown
  background?: unknown
  bounds?: unknown
  initialView?: unknown
  maxZoom?: unknown
  fillOnOpen?: unknown
  zoomOutFills?: unknown
  layers?: unknown
  icons?: unknown
  labels?: unknown
  anchors?: unknown
  marks?: unknown
}): MapMeta {
  const bounds = toBounds(raw.bounds, 'bounds')
  const initialView = toBounds(raw.initialView, 'initialView')
  const layerFiles = (Array.isArray(raw.layers) ? raw.layers : []).map((value: unknown, i): LayerFile => {
    const layer = value as { file?: unknown; bounds?: unknown }
    if (typeof layer.file !== 'string' || !layer.file) throw new Error(`map metadata: layer ${i} needs a file`)
    const layerBounds = toBounds(layer.bounds, `layer ${layer.file} bounds`)
    const inside = layerBounds.every(([lat, lng]) => isInsideBounds({ lat, lng }, bounds))
    if (!inside) throw new Error(`map metadata: layer ${layer.file} must lie inside the map bounds`)
    return { file: layer.file, bounds: layerBounds }
  })
  const iconFiles = Object.fromEntries(
    Object.entries((raw.icons ?? {}) as Record<string, unknown>).map(([key, file]) => {
      if (typeof file !== 'string' || !file) throw new Error(`map metadata: icon ${key} needs a file`)
      return [key, file] as const
    }),
  )
  const labels = (Array.isArray(raw.labels) ? raw.labels : []).map((value: unknown) => toLabel(value, bounds, iconFiles))
  const anchors = Object.entries(raw.anchors ?? {}).map(([key, value]) => {
    if (!isPair(value) || !isInsideBounds({ lat: value[0], lng: value[1] }, bounds)) {
      throw new Error(`map metadata: anchor ${key} must be a [lat, lng] inside the image`)
    }
    return [key, value] as const
  })
  const marks = (Array.isArray(raw.marks) ? raw.marks : []).map((value: unknown): MapMark => {
    const m = value as Partial<MapMark>
    const spot = m.spot === undefined ? undefined : toSpot(m.spot, bounds)
    if (spot === null) throw new Error(`map metadata: mark ${String(m.id)} has a spot outside the map`)
    const ok =
      typeof m.id === 'number' &&
      typeof m.kind === 'string' &&
      typeof m.zone === 'string' &&
      typeof m.lat === 'number' &&
      typeof m.lng === 'number' &&
      isInsideBounds({ lat: m.lat, lng: m.lng }, bounds)
    if (!ok) throw new Error(`map metadata: mark ${String(m.id)} needs id, kind, zone and a lat/lng inside the image`)
    return { id: m.id!, kind: m.kind!, zone: m.zone!, lat: m.lat!, lng: m.lng!, ...(spot ? { spot } : {}) }
  })
  return {
    bounds,
    initialView,
    maxZoom: typeof raw.maxZoom === 'number' && Number.isFinite(raw.maxZoom) ? raw.maxZoom : null,
    fillOnOpen: raw.fillOnOpen !== false,
    zoomOutFills: raw.zoomOutFills === true,
    layerFiles,
    iconFiles,
    labels,
    marks,
    attribution: typeof raw.attribution === 'string' ? raw.attribution : '',
    background: isColour(raw.background) ? raw.background : null,
    anchors: Object.fromEntries(anchors),
  }
}

/** The map's images: the layers and icons the metadata lists (by file name), or one image covering the whole map. */
export function withImages({ layerFiles, iconFiles, ...meta }: MapMeta, images: string | Readonly<Record<string, string>>): FestivalMap {
  if (typeof images === 'string') return { ...meta, layers: [{ url: images, bounds: meta.bounds }], icons: {} }
  if (layerFiles.length === 0) throw new Error('map metadata: no layers listed')
  const bundled = (file: string) => {
    const url = images[file]
    if (!url) throw new Error(`map metadata: ${file} is not bundled`)
    return url
  }
  const layers = layerFiles.map(({ file, bounds }) => ({ url: bundled(file), bounds }))
  const icons = Object.fromEntries(Object.entries(iconFiles).map(([key, file]) => [key, bundled(file)]))
  return { ...meta, layers, icons }
}

/** Bundled files of a map folder, keyed by their path inside it ("layer1.svg", "icons/toilet.svg"). */
const folder = (prefix: string, files: Record<string, string>) =>
  Object.fromEntries(Object.entries(files).map(([path, url]) => [path.slice(prefix.length), url]))

const MAPS: Record<string, FestivalMap> = {
  [GRAND_MINT_SERIES]: withImages(parseMapMeta(gmfMeta), gmfImage),
  // The layered map redrawn from the official site map (scripts/map/layers/pentaport/): the big area map's ground
  // under the venue map's ground and operations; its pins, names and the station are drawn by the app.
  [PENTAPORT_SERIES]: withImages(
    parseMapMeta(pentaportMeta),
    folder('../../assets/maps/pentaport/', import.meta.glob<string>('../../assets/maps/pentaport/**/*.svg', { eager: true, query: '?url', import: 'default' })),
  ),
}

/** The map of a festival code; use festivalMapFor (data/catalog) to go from a festival id. */
export const seriesMapFor = (seriesCode: string): FestivalMap | null => MAPS[seriesCode] ?? null
